-- Server-only RPCs. Service role must never be sent to a browser.
create table private.rate_limits(key text primary key,window_start timestamptz not null,count int not null);
create function public.runtime_rate(p jsonb) returns boolean language plpgsql security definer set search_path='' as $$declare n int;begin insert into private.rate_limits values(p->>'key',date_trunc('minute',now()),1)on conflict(key)do update set count=case when rate_limits.window_start<date_trunc('minute',now())then 1 else rate_limits.count+1 end,window_start=date_trunc('minute',now()) returning count into n;return n<=(p->>'limit')::int;end$$;
create function public.runtime_login_lookup(p jsonb) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',m.id,'credentialVersion',m.credential_version,'mustChangePassword',m.must_change_password,'role',m.role)from private.login_identifiers l join public.memberships m on m.id=l.user_id join public.schools s on s.id=m.school_id where s.code=lower(p->>'schoolCode') and l.normalized=lower(p->>'loginId') and l.current and m.active and s.status='active'$$;
create function public.runtime_session_create(p jsonb) returns void language sql security definer set search_path='' as $$insert into private.sessions(token_hash,user_id,encrypted_provider_tokens,csrf_hash,expires_at,credential_version)values(p->>'hash',(p->>'userId')::uuid,p->>'tokens',p->>'csrfHash',now()+interval '12 hours',(p->>'credentialVersion')::int)$$;
create function public.runtime_session(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare se private.sessions;m public.memberships;active boolean;begin select * into se from private.sessions where token_hash=p->>'hash' for update;if not found or se.revoked_at is not null or se.expires_at<=now() then return null;end if;select * into m from public.memberships where id=se.user_id;select exists(select 1 from public.attempts where student_id=m.id and status='in_progress' and deadline>now())into active;if not m.active or se.credential_version<>m.credential_version or (se.last_seen_at<now()-interval '30 minutes' and not active) or exists(select 1 from public.schools where id=m.school_id and status='suspended')then update private.sessions set revoked_at=now()where token_hash=se.token_hash;return null;end if;update private.sessions set last_seen_at=now()where token_hash=se.token_hash;return jsonb_build_object('userId',m.id,'schoolId',m.school_id,'role',m.role,'tokens',se.encrypted_provider_tokens,'csrfHash',se.csrf_hash,'expiresAt',se.expires_at,'reauthenticatedAt',se.reauthenticated_at,'mustChangePassword',m.must_change_password);end$$;
create function public.runtime_session_refresh(p jsonb)returns void language sql security definer set search_path='' as $$update private.sessions set encrypted_provider_tokens=p->>'tokens'where token_hash=p->>'hash' and revoked_at is null$$;
create function public.runtime_session_revoke(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare u uuid;s uuid;r text;begin select user_id into u from private.sessions where token_hash=p->>'hash';update private.sessions set revoked_at=now() where token_hash=p->>'hash';if u is not null then select school_id,role into s,r from public.memberships where id=u;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action)values(s,u,r,u,'account.logout');end if;end$$;
create function public.runtime_sweep(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a record;c record;e text;recipient uuid;n int:=0;begin for a in select id from public.attempts where status='in_progress' and deadline<=now() order by deadline limit 200 for update skip locked loop perform private.finalize(a.id);n:=n+1;end loop;
for c in select cy.*,q.student_id,q.state,q.teacher_id as reminder_teacher from public.query_cycles cy join public.queries q on q.id=cy.query_id and q.cycle=cy.cycle join public.schools s on s.id=q.school_id where cy.solution_delivered_at is null and q.state not in ('resolved','withdrawn')and s.status='active' loop for e in select unnest(array['80','due','escalate']) loop if (e='80' and now()>=c.started_at+(c.due_at-c.started_at)*0.8)or(e='due' and now()>=c.due_at)or(e='escalate' and now()>=c.due_at+interval '24 hours')then
for recipient in select case when e='escalate' then m.id else c.reminder_teacher end from public.memberships m where m.school_id=c.school_id and m.active and (e='escalate' and m.role='administrator' or e<>'escalate' and m.id=c.reminder_teacher)loop insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(c.school_id,recipient,'query-reminder:'||c.query_id||':'||c.cycle||':'||c.deadline_revision||':'||e,'query.reminder',c.query_id)on conflict do nothing;end loop;
if e='due' then insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(c.school_id,c.student_id,'query-overdue:'||c.query_id||':'||c.cycle||':'||c.deadline_revision,'query.delayed',c.query_id)on conflict do nothing;end if;end if;end loop;end loop;
update public.outbox set status='failed',error_code='RETRY_EXHAUSTED' where attempts>=4 and status in ('pending','dispatched','processing')and(lease_until is null or lease_until<now());
update public.outbox set status='pending',lease_until=null where status in ('processing','dispatched')and lease_until<now();delete from private.rate_limits where window_start<now()-interval '1 hour';return jsonb_build_object('finalized',n);end$$;
create function public.runtime_dispatch(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare jobs jsonb;begin with claimed as (select id from public.outbox where status='pending' and available_at<=now() order by available_at limit 100 for update skip locked),changed as(update public.outbox set status='dispatched',lease_until=now()+interval '5 minutes' where id in(select id from claimed)returning id,kind)select coalesce(jsonb_agg(to_jsonb(changed)),'[]')into jobs from changed;return jobs;end$$;
create function public.runtime_claim(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.outbox;data jsonb;begin update public.outbox set run_token=gen_random_uuid(),status='processing',attempts=attempts+1,lease_until=now()+interval '2 minutes' where id=(p->>'id')::uuid and(status in ('pending','dispatched')or status='processing' and lease_until<now())and attempts<4 returning * into j;if not found then return null;end if;
if j.kind='subjective' then select jsonb_build_object('question',q.content,'key',k.key,'response',a.response)into data from public.exam_questions q join private.question_keys k on k.version_id=q.version_id and k.question_id=q.id join public.attempts at on at.version_id=q.version_id left join public.answers a on a.attempt_id=at.id and a.question_id=q.id where at.id=(j.payload->>'attemptId')::uuid and q.id=(j.payload->>'questionId')::uuid;
elsif j.kind='insight' then select jsonb_build_object('sourceVersion',i.source_version,'correction',i.correction,'suppressed',i.suppressed,'results',(select jsonb_agg(jsonb_build_object('id',r.id,'total',r.total,'maximum',r.maximum,'scores',r.scores))from public.results r where r.student_id=i.student_id))into data from public.student_insights i where i.student_id=(j.payload->>'studentId')::uuid;end if;
return jsonb_build_object('id',j.id,'runToken',j.run_token,'kind',j.kind,'schoolId',j.school_id,'payload',j.payload,'data',data,'attempts',j.attempts);end$$;
create function public.runtime_finish(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare j public.outbox;begin select * into j from public.outbox where id=(p->>'id')::uuid for update;if j.status<>'processing' or j.run_token is distinct from (p->>'runToken')::uuid then return;end if;if p->>'status'='done' and j.kind='subjective' then update private.grades set ai_suggestion=p->'result' where attempt_id=(j.payload->>'attemptId')::uuid and question_id=(j.payload->>'questionId')::uuid and reviewer is null;elsif p->>'status'='done' and j.kind='insight' then update public.student_insights set content=p->'result',status='ready',updated_at=now() where student_id=(j.payload->>'studentId')::uuid and source_version=(p->>'sourceVersion')::bigint and not suppressed and correction is null;elsif j.kind='insight' and p->>'status' in ('failed','unavailable') then update public.student_insights set status=p->>'status'where student_id=(j.payload->>'studentId')::uuid and source_version=(p->>'sourceVersion')::bigint;end if;
update public.outbox set status=p->>'status',result=case when p->>'status'='done' then p->'result'else null end,error_code=p->>'errorCode',lease_until=null,available_at=now()+interval '30 seconds'where id=j.id;end$$;
create function public.runtime_reserve_ai(p jsonb) returns boolean language plpgsql security definer set search_path='' as $$declare s uuid:=(p->>'schoolId')::uuid;lim int;used int;begin select ai_limit into lim from public.subscriptions where school_id=s and now()between starts_at and ends_at for update;if not found then return false;end if;select coalesce(sum(u.used),0)into used from private.ai_usage u where u.school_id=s and month=date_trunc('month',now())::date;if used>=lim then return false;end if;insert into private.ai_usage values(s,date_trunc('month',now())::date,p->>'kind',1)on conflict(school_id,month,kind)do update set used=ai_usage.used+1;return true;end$$;
-- No default EXECUTE for later server-only functions.
revoke execute on function public.runtime_rate(jsonb),public.runtime_login_lookup(jsonb),public.runtime_session_create(jsonb),public.runtime_session(jsonb),public.runtime_session_refresh(jsonb),public.runtime_session_revoke(jsonb),public.runtime_sweep(jsonb),public.runtime_dispatch(jsonb),public.runtime_claim(jsonb),public.runtime_finish(jsonb),public.runtime_reserve_ai(jsonb) from public,anon,authenticated;
grant execute on function public.runtime_rate(jsonb),public.runtime_login_lookup(jsonb),public.runtime_session_create(jsonb),public.runtime_session(jsonb),public.runtime_session_refresh(jsonb),public.runtime_session_revoke(jsonb),public.runtime_sweep(jsonb),public.runtime_dispatch(jsonb),public.runtime_claim(jsonb),public.runtime_finish(jsonb),public.runtime_reserve_ai(jsonb) to service_role;
